def transform(grid):
    """Rotate the sparse color key clockwise and expand it over the 8-mask."""
    h, w = len(grid), len(grid[0])
    key = [(r, c, grid[r][c])
           for r in range(h) for c in range(w)
           if grid[r][c] not in (0, 8)]
    targets = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    out = [row[:] for row in grid]
    if not key or not targets:
        return out

    r0, r1 = min(r for r, c, v in key), max(r for r, c, v in key)
    c0, c1 = min(c for r, c, v in key), max(c for r, c, v in key)
    kh, kw = r1-r0+1, c1-c0+1
    motif = [[0] * kw for _ in range(kh)]
    for r, c, color in key:
        motif[r-r0][c-c0] = color
    # Clockwise quarter-turn: output dimensions kw x kh.
    motif = [[motif[kh-1-r][c] for r in range(kh)] for c in range(kw)]

    # Repeated cells have a common side length, the GCD of runs of 8s.
    scale = 0
    for r in range(h):
        run = 0
        for c in range(w + 1):
            if c < w and grid[r][c] == 8:
                run += 1
            elif run:
                scale = gcd(scale, run)
                run = 0
    for c in range(w):
        run = 0
        for r in range(h + 1):
            if r < h and grid[r][c] == 8:
                run += 1
            elif run:
                scale = gcd(scale, run)
                run = 0
    if scale == 0:
        return out

    top = min(r for r, c in targets)
    left = min(c for r, c in targets)
    for r, c in targets:
        mr = (r-top) // scale
        mc = (c-left) // scale
        color = motif[mr][mc]
        if color:
            out[r][c] = color
    return out
